let playerSession=null,cloudDirty=false,cloudBusy=false,cloudTimer=0,cloudPending=null,cloudStatus='Saved on this device';
try{playerSession=JSON.parse(localStorage.getItem('quest-clash-account')||'null')}catch{}
function storePlayerSession(){if(playerSession)localStorage.setItem('quest-clash-account',JSON.stringify(playerSession));else localStorage.removeItem('quest-clash-account')}
async function playerRequest(action,data={}){if(location.protocol==='file:')throw Error('Open the online game to use player login. Progress still saves in this browser.');const response=await fetch('/api/account/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,token:playerSession?.token})});const value=await response.json();if(!response.ok){const e=Error(value.error||'Progress service unavailable.');e.status=response.status;throw e}return value}
function updateCloudLabel(){const b=document.querySelector('[data-player-account]');if(b){b.textContent=playerSession?'☁ '+playerSession.username:'☁ Save / Log in';b.title=cloudStatus}const status=document.querySelector('#cloud-save-status');if(status)status.textContent=cloudStatus}
async function syncPlayerProgress(){if(!playerSession||!cloudDirty||cloudBusy||cloudPending)return;cloudBusy=true;const captured=JSON.stringify(profile),session=playerSession;try{const result=await playerRequest('save',{revision:session.revision,profile:JSON.parse(captured)});if(playerSession!==session)return;session.revision=result.revision;storePlayerSession();cloudDirty=JSON.stringify(profile)!==captured;cloudStatus='Cloud saved · Level '+playerLevel();if(cloudDirty)cloudTimer=setTimeout(syncPlayerProgress,1500)}catch(e){cloudStatus=e.message;if(e.status===409||e.status===401){playerSession=null;storePlayerSession();toast(e.message)}else cloudTimer=setTimeout(syncPlayerProgress,15000)}finally{cloudBusy=false;updateCloudLabel()}}
const cloudLocalSave=save;save=function(){cloudLocalSave();if(playerSession&&!cloudPending){cloudDirty=true;cloudStatus='Saved on this device · syncing…';clearTimeout(cloudTimer);cloudTimer=setTimeout(syncPlayerProgress,1500)}updateCloudLabel()};
function openPlayerAccount(){if(game||live||quiz){toast('Finish or leave this adventure before changing player login.');return}if(cloudPending){cloudPending=null;playerSession=null;storePlayerSession()}const online=location.protocol!=='file:';openModal(`${topModal('PLAYER PROGRESS')}<h2 id="modal-title">Keep your adventure.</h2><p class="sub">Levels, credits, avatars and stages save automatically on this browser. Use a player login to continue on another device.</p><p class="notice" id="cloud-save-status">${cloudStatus}</p>${playerSession?`<p>Signed in as <b>${playerSession.username}</b>. Cloud saving is automatic while you play.</p><div class="modal-actions"><button class="primary" data-account-action="sync">Save now</button><button class="secondary" data-account-action="logout">Log out</button></div>`:`<form id="player-account-form"><label>Username <input id="account-username" name="username" autocomplete="username" pattern="[A-Za-z0-9_-]{3,20}" minlength="3" maxlength="20" placeholder="e.g. cometpup42" required></label><label>Password <input id="account-password" name="password" type="password" autocomplete="current-password" minlength="8" maxlength="128" placeholder="At least 8 characters" required></label><p class="hint">Use a nickname. No real name or email needed. Keep the password with a parent; password recovery is not available.</p><p id="account-error" role="status"></p><div class="modal-actions"><button class="primary" type="submit" name="intent" value="login" ${online?'':'disabled'}>Log in & continue</button><button class="secondary" type="submit" name="intent" value="register" ${online?'':'disabled'}>Create login & save this progress</button></div></form>`}<p class="notice">Cloud saves include learning history and game settings. Play on one device at a time. Logging out keeps this browser’s current progress.</p>`)}
document.addEventListener('submit',async event=>{if(event.target.id!=='player-account-form')return;event.preventDefault();const form=event.target,buttons=[...form.querySelectorAll('button')],error=form.querySelector('#account-error');buttons.forEach(b=>b.disabled=true);try{const intent=event.submitter?.value||'login',result=await playerRequest(intent,{username:form.querySelector('#account-username').value,password:form.querySelector('#account-password').value,...intent==='register'?{profile}: {}});playerSession={username:result.username,token:result.token,revision:result.revision};storePlayerSession();cloudDirty=false;if(intent==='register'){cloudStatus='Cloud saved · Level '+playerLevel();closeModal();updateCloudLabel();toast('Login created. Your adventure is saved.')}else{cloudPending=result.profile;const level=Math.min(100,1+Math.floor(result.profile.xp/150));openModal(`${topModal('CHOOSE YOUR SAVE')}<h2 id="modal-title">Welcome back, ${result.username}.</h2><p>Your cloud save: <b>Level ${level} · ${result.profile.coins} credits</b><br>This browser: <b>Level ${playerLevel()} · ${profile.coins} credits</b></p><p>Choose which progress to continue. The selected save becomes your cloud progress.</p><div class="modal-actions"><button class="primary" data-account-action="restore">Continue cloud save</button><button class="secondary" data-account-action="keep">Keep this browser’s progress</button></div>`)} }catch(e){error.textContent=e.message}finally{buttons.forEach(b=>b.disabled=false)}});
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-player-account')){openPlayerAccount();return}const action=b.dataset.accountAction;if(!action)return;if(action==='restore'&&cloudPending){profile={...fresh(),...cloudPending};cloudPending=null;cloudDirty=false;ensureAvatar();initialiseQuestionHistory();cloudLocalSave();petTab=ensureAvatar().species;unlockNoticeRank=highestUnlockedRank().rank;cloudStatus='Cloud save restored · Level '+playerLevel();closeModal();navigate('home');updateCloudLabel();toast('Welcome back! Continue your adventure.')}if(action==='keep'){cloudPending=null;cloudDirty=true;closeModal();await syncPlayerProgress();toast(cloudStatus)}if(action==='sync'){cloudDirty=true;await syncPlayerProgress();updateCloudLabel()}if(action==='logout'){await syncPlayerProgress();try{await playerRequest('logout')}catch{}playerSession=null;cloudPending=null;cloudDirty=false;storePlayerSession();cloudStatus='Saved on this device';closeModal();updateCloudLabel()}});
document.querySelector('.playerbar')?.insertAdjacentHTML('afterbegin','<button class="friends-launch" data-player-account>☁ Save / Log in</button>');updateCloudLabel();
// Never overwrite a newer cloud save simply by opening an old browser tab.
if(playerSession)playerRequest('load').then(result=>{if(result.revision!==playerSession.revision){cloudStatus='Newer cloud progress available. Log in to choose your save.';playerSession=null;storePlayerSession()}else cloudStatus='Cloud connected · progress saves automatically';updateCloudLabel()}).catch(e=>{cloudStatus=e.message;updateCloudLabel()});
window.addEventListener('online',syncPlayerProgress);
